import {allItems,category,label} from '../data.js';
import {heading,target,audioButtons,esc,modal} from '../ui.js';
import {normalize} from '../srs.js';
export async function phrasebook(c){const l=c.store.lang();let items=[...await allItems(c.language.code),...c.store.state().custom.filter(x=>x.language===c.language.code)];c.register(items);const themes=[...new Set(items.filter(x=>x.category==='nouns').flatMap(x=>x.tags||[]))].filter(x=>x!=='beginner');const categories=[...new Set(items.map(x=>x.category))];let limit=40;
document.querySelector('#view').innerHTML=heading('Words for the world outside.',`${items.length} words & expressions · ${c.language.variety}`)+`<div class="toolbar"><input id="search" aria-label="Search words, pronunciation, or English" placeholder="Search a word, a meaning, a little curiosity…"><select id="category" aria-label="Filter category"><option value="">All topics</option>${categories.map(x=>`<option value="${esc(x)}">${label(x)}</option>`).join('')}${themes.map(x=>`<option value="theme:${esc(x)}">Nouns · ${label(x)}</option>`).join('')}</select><select id="filter" aria-label="Filter collection"><option value="">All words</option><option value="favorites">Starred words</option><option value="added">My flashcards</option><option value="review">Needs native review</option></select></div><p id="count" class="muted"></p><div id="words" class="word-list"></div><button class="button secondary" id="more" style="margin-top:20px">Show more words</button>`;
const render=()=>{const q=normalize(document.querySelector('#search').value),cat=document.querySelector('#category').value,filter=document.querySelector('#filter').value;const filtered=items.filter(x=>(!cat||x.category===cat||cat.startsWith('theme:')&&x.tags?.includes(cat.slice(6)))&&(!q||normalize([x.target,x.native,x.transliteration].join(' ')).includes(q))&&(!filter||filter==='review'&&x.needsReview||l[filter]?.includes(x.id)));document.querySelector('#count').textContent=`${filtered.length} little discoveries`;document.querySelector('#more').hidden=filtered.length<=limit;document.querySelector('#words').innerHTML=filtered.length?filtered.slice(0,limit).map(x=>`<article class="word-row"><div class="word-main">${target(x,c.language)}${c.store.state().settings.transliteration&&x.transliteration?`<div class="translit">${esc(x.transliteration)}</div>`:''}${c.store.state().settings.ipa&&x.ipa?`<div class="translit">/${esc(x.ipa)}/</div>`:''}</div><div class="word-meaning">${esc(x.native)}${x.eastern?` <small>${esc(x.eastern)}</small>`:''}<br><small>${esc(x.category)} ${x.needsReview?'· Native review pending':''}</small></div>${audioButtons(x.id)}<button class="small-button ${l.favorites.includes(x.id)?'selected':''}" data-star="${esc(x.id)}" aria-label="${l.favorites.includes(x.id)?'Unstar':'Star'} ${esc(x.native)}" aria-pressed="${l.favorites.includes(x.id)}">${l.favorites.includes(x.id)?'★':'☆'}</button><button class="small-button ${l.added.includes(x.id)?'selected':''}" data-add="${esc(x.id)}" aria-label="Add ${esc(x.native)} to flashcards">${l.added.includes(x.id)?'✓':'+'}</button><button class="small-button" data-detail="${esc(x.id)}" aria-label="Details for ${esc(x.native)}">⋯</button></article>`).join(''):'<div class="empty">No words here yet. Try another search, or star a few favorites.</div>';};
for(const id of ['search','category','filter'])document.querySelector('#'+id).addEventListener('input',()=>{limit=40;render();});document.querySelector('#more').onclick=()=>{limit+=40;render();};
const click=e=>{const star=e.target.closest('[data-star]'),add=e.target.closest('[data-add]'),detail=e.target.closest('[data-detail]');if(star){const id=star.dataset.star;l.favorites=l.favorites.includes(id)?l.favorites.filter(x=>x!==id):[...l.favorites,id];c.store.save();render();}if(add){const id=add.dataset.add;if(!l.added.includes(id))l.added.push(id);c.store.save();render();c.toast('Added to your flashcards.');}if(detail){const x=items.find(x=>x.id===detail.dataset.detail);modal(`<h2>${target(x,c.language)}</h2><p>${esc(x.native)}</p>${audioButtons(x.id)}${x.transliteration?`<p>${esc(x.transliteration)} <small>· provisional pronunciation guide</small></p>`:''}${x.plural?`<p>Plural: <bdi dir="${c.language.direction}">${esc(x.plural)}</bdi></p>`:''}${x.article&&c.store.state().settings.articles?`<p>Article: ${esc(x.article)} · Indefinite: ${esc(x.indefiniteArticle)} · Gender: ${esc(x.gender)}</p>`:''}${x.example?`<p>${esc(x.example.target)}<br>${esc(x.example.native)}</p>`:''}<p>${esc(x.notes)}</p>${x.needsReview?'<p class="banner">This entry is flagged for native review, including Arabic vowels, morphology, and pronunciation. Treat it as a study draft.</p>':''}`);}};
document.querySelector('#words').addEventListener('click',click);render();}
export function parseTSV(text){return text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean).map(line=>line.split('\t')).filter(row=>row.length>=2&&row[0].trim()&&row[1].trim());}
export async function decks(c){const s=c.store.state(),code=c.language.code;let selected=s.decks.find(x=>x.language===code)?.id||'';
function render(){const decks=s.decks.filter(x=>x.language===code),custom=s.custom.filter(x=>x.language===code&&(!selected||x.deckId===selected));c.register(custom);document.querySelector('#view').innerHTML=heading('Your words. Your way.','Build a collection around the things you care about.')+`<div class="grid2"><section class="card"><h2>Make a little collection</h2><form id="new-deck"><label class="field">Deck name<input name="name" required maxlength="80" placeholder="Words for our next trip"></label><button class="button">Create deck</button></form><hr><label class="field">Your deck<select id="deck-select"><option value="">All custom words</option>${decks.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><a class="button secondary" href="#/${code}/flashcards/deck=${encodeURIComponent(selected||'custom')}">Study this collection</a> <a class="button secondary" href="#/${code}/quiz/deck=${encodeURIComponent(selected||'custom')}">Quiz</a> <a class="button secondary" href="#/${code}/spelling/deck=${encodeURIComponent(selected||'custom')}">Spelling</a><h3 style="margin-top:25px">Add a word</h3><form id="new-word"><label class="field">${c.language.name}<input name="target" dir="${c.language.direction}" required maxlength="200"></label><label class="field">English meaning<input name="native" required maxlength="200"></label><label class="field">Pronunciation guide (optional)<input name="transliteration" maxlength="200"></label><button class="button">Plant this word +</button></form></section><section class="card"><h2>Bring words with you</h2><p class="muted">Paste tab-separated text: target, English, optional pronunciation. One word per line. Compatible with basic Quizlet and Anki text exports.</p><textarea id="tsv" aria-label="Tab-separated vocabulary" placeholder="ciao&#9;hello"></textarea><div class="flex" style="margin-top:12px"><button class="button secondary" id="import-tsv">Import text</button><label class="button secondary">Open TSV<input id="tsv-file" type="file" accept=".tsv,.txt,.csv" class="sr-only"></label><button class="button secondary" id="export-tsv">Export TSV</button></div><p class="muted"><small>Custom words live on this device and are included in your progress backup. Add original recordings to the static audio folder using the word’s ID.</small></p><h3 style="margin-top:25px">${custom.length} words in this collection</h3><div class="word-list">${custom.slice(-20).map(x=>`<div class="word-row"><div class="word-main">${target(x,c.language)}<small>${esc(x.native)}</small></div>${audioButtons(x.id)}<button class="small-button" data-delete="${esc(x.id)}" aria-label="Remove ${esc(x.native)}">×</button></div>`).join('')||'<p class="muted">Your next favorite word can start here.</p>'}</div></section></div>`;
document.querySelector('#deck-select').onchange=e=>{selected=e.target.value;render();};document.querySelector('#new-deck').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);selected=crypto.randomUUID();s.decks.push({id:selected,name:String(f.get('name')).trim(),language:code});c.store.save();render();};
function add(t,n,tr=''){s.custom.push({id:`${code}-custom-${crypto.randomUUID()}`,target:t.trim(),native:n.trim(),transliteration:tr.trim(),category:'custom',language:code,deckId:selected,notes:'Your own vocabulary.'});}
document.querySelector('#new-word').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);add(String(f.get('target')),String(f.get('native')),String(f.get('transliteration')));c.store.save();render();c.toast('A new word, planted.');};document.querySelector('#import-tsv').onclick=()=>{const rows=parseTSV(document.querySelector('#tsv').value).slice(0,1000);for(const [t,n,tr] of rows)add(t,n,tr);c.store.save();render();c.toast(`${rows.length} words imported.`);};document.querySelector('#tsv-file').onchange=async e=>{if(e.target.files[0])document.querySelector('#tsv').value=await e.target.files[0].text();};document.querySelector('#export-tsv').onclick=()=>c.store.download('parola-vocabulary.tsv',custom.map(x=>[x.target,x.native,x.transliteration||''].map(v=>v.replace(/[\t\r\n]/g,' ')).join('\t')).join('\n'),'text/tab-separated-values');for(const b of document.querySelectorAll('[data-delete]'))b.onclick=()=>{s.custom=s.custom.filter(x=>x.id!==b.dataset.delete);c.store.save();render();};}render();}
export async function reader(c){const all=await allItems(c.language.code);c.register(all);document.querySelector('#view').innerHTML=heading('A little reading room.','Paste a text, then tap a word to look for it in your offline dictionary.')+`<section class="card"><textarea id="reader-text" dir="${c.language.direction}" aria-label="Text to read" placeholder="Paste a few sentences here…"></textarea><button class="button" id="read" style="margin-top:12px">Let’s read</button><div id="reading" class="reader" dir="${c.language.direction}"></div><div id="definition" class="banner" hidden></div></section>`;document.querySelector('#read').onclick=()=>{const words=document.querySelector('#reader-text').value.split(/(\s+)/);document.querySelector('#reading').innerHTML=words.map((w,i)=>/\S/.test(w)?`<button data-word="${i}">${esc(w)}</button>`:esc(w)).join('');for(const b of document.querySelectorAll('[data-word]'))b.onclick=()=>{const q=normalize(words[Number(b.dataset.word)]),x=all.find(x=>normalize(x.target)===q||normalize(x.target.replace(/^(il |la |lo |l[’']|un |una |ال)/,''))===q);const d=document.querySelector('#definition');d.hidden=false;d.innerHTML=x?`${target(x,c.language)} · ${esc(x.native)} ${audioButtons(x.id)}`:'This word isn’t in the local dictionary yet. You can add it to your own deck.';};};}
export async function dialogues(c){const items=[...await category(c.language.code,'greetings'),...await category(c.language.code,'phrases')];c.register(items);const groups=[['Meeting someone',['Hello','How are you?','I’m well.','What is your name?','My name is…','Nice to meet you.']],['At the restaurant',['A table for two, please.','The menu, please.','I am vegetarian.','It is delicious.','The bill, please.']],['Finding your way',['Excuse me','Where is the bathroom?','Turn right.','Go straight.','Thank you']]];document.querySelector('#view').innerHTML=heading('Let’s have a small conversation.','Listen line by line. Hide one speaker and take their part.')+`<div class="toolbar"><select id="dialogue-choice" aria-label="Choose dialogue">${groups.map((x,i)=>`<option value="${i}">${x[0]}</option>`).join('')}</select><select id="role" aria-label="Role play"><option value="all">Show both speakers</option><option value="0">I’ll be speaker A</option><option value="1">I’ll be speaker B</option></select></div><div class="card" id="dialogue-lines"></div>`;function render(){const index=Number(document.querySelector('#dialogue-choice').value),role=document.querySelector('#role').value;document.querySelector('#dialogue-lines').innerHTML=groups[index][1].map((en,i)=>{const w=items.find(x=>x.native===en);if(!w)return '';return `<div class="dialogue-line"><strong>Speaker ${i%2?'B':'A'}</strong>${role===String(i%2)?`<details><summary>${esc(en)} · reveal your line</summary>${target(w,c.language)} ${audioButtons(w.id)}</details>`:`${target(w,c.language)} ${audioButtons(w.id)}<div class="translit">${esc(en)}</div>`}</div>`;}).join('');}document.querySelector('#dialogue-choice').onchange=render;document.querySelector('#role').onchange=render;render();}
